int note_to_semitone(const char *note) {
    if (strcmp(note, "C") == 0) return 0;
    if (strcmp(note, "C#") == 0) return 1;
    if (strcmp(note, "D") == 0) return 2;
    if (strcmp(note, "D#") == 0) return 3;
    if (strcmp(note, "E") == 0) return 4;
    if (strcmp(note, "F") == 0) return 5;
    if (strcmp(note, "F#") == 0) return 6;
    if (strcmp(note, "G") == 0) return 7;
    if (strcmp(note, "G#") == 0) return 8;
    if (strcmp(note, "A") == 0) return 9;
    if (strcmp(note, "A#") == 0) return 10;
    if (strcmp(note, "B") == 0) return 11;
    return -1; // shouldn't happen
}

int main() {
    int n, m;

    while (1) {
        scanf("%d %d", &n, &m);
        if (n == 0 && m == 0) break;

        int plates[n];
        for (int i = 0; i < n; i++) {
            char note[3];
            scanf("%s", note);
            plates[i] = note_to_semitone(note);
        }

        int song[m];
        for (int i = 0; i < m; i++) {
            char note[3];
            scanf("%s", note);
            song[i] = note_to_semitone(note);
        }

        // dp[i][j] = can we reach plate i and have matched first j notes of song?
        // We'll use a 2-row DP to save memory
        bool dp[2][m+1];
        memset(dp, 0, sizeof(dp));

        // Initialization: before any step, we have matched 0 notes
        // We can start at any plate
        for (int i = 0; i < n; i++) {
            if (plates[i] == song[0]) {
                dp[i % 2][1] = true;
            } else {
                dp[i % 2][0] = true; // can be at plate i with 0 matches
            }
        }

        // Actually we need to allow starting anywhere without playing a note
        // Reset: we can be at any plate with 0 notes matched
        memset(dp, 0, sizeof(dp));
        for (int i = 0; i < n; i++) {
            dp[i % 2][0] = true;
        }

        for (int i = 0; i < n; i++) {
            int cur = i % 2;
            int next = (i + 1) % 2;
            // reset next row for next iteration
            if (i + 1 < n) {
                memset(dp[next], 0, sizeof(dp[next]));
            }

            for (int j = 0; j <= m; j++) {
                if (!dp[cur][j]) continue;

                // Option: stay? No, we must descend (move to next plate each step)
                // Actually the problem says "descend", so we always move to adjacent step.
                // We only consider moving forward.

                // Move to next plate if exists
                if (i + 1 < n) {
                    // don't play a note
                    dp[next][j] = true;
                    // play the note on the new plate
                    if (j < m && plates[i+1] == song[j]) {
                        dp[next][j+1] = true;
                    }
                }
            }
        }

        // Check if we can reach end with all notes matched
        bool possible = false;
        for (int i = 0; i < n; i++) {
            if (dp[i % 2][m]) {
                possible = true;
                break;
            }
        }

        printf("%s\n", possible ? "Yes" : "No");
    }

    return 0;
}

