static int note_id(const char *s) {
    if (strcmp(s, "C") == 0) return 0;
    if (strcmp(s, "C#") == 0) return 1;
    if (strcmp(s, "D") == 0) return 2;
    if (strcmp(s, "D#") == 0) return 3;
    if (strcmp(s, "E") == 0) return 4;
    if (strcmp(s, "F") == 0) return 5;
    if (strcmp(s, "F#") == 0) return 6;
    if (strcmp(s, "G") == 0) return 7;
    if (strcmp(s, "G#") == 0) return 8;
    if (strcmp(s, "A") == 0) return 9;
    if (strcmp(s, "A#") == 0) return 10;
    return 11; /* B */
}

int main(void) {
    int n, m;
    while (scanf("%d %d", &n, &m) == 2) {
        if (n == 0 && m == 0) break;

        int a[MAXN];
        int song[MAXM];
        char buf[10];

        for (int i = 1; i <= n; i++) {
            scanf("%s", buf);
            a[i] = note_id(buf);
        }
        for (int i = 1; i <= m; i++) {
            scanf("%s", buf);
            song[i] = note_id(buf);
        }

        /* Build DAG of possible downward moves:
           from step i you may move to i+1 or i+2 while descending.
           A sound is produced on the step landed on.
           Start above step 1, so first sounded step can be 1.
        */

        /* dp[i][k] = can be at step i after playing first k notes,
           with note on step i equal to song[k]. */
        static char dp[MAXN][MAXM];
        for (int i = 0; i <= n; i++)
            for (int k = 0; k <= m; k++)
                dp[i][k] = 0;

        for (int i = 1; i <= n; i++) {
            if (a[i] == song[1]) {
                if (i == 1 || i == 2) dp[i][1] = 1;
            }
        }

        for (int k = 1; k < m; k++) {
            for (int i = 1; i <= n; i++) {
                if (!dp[i][k]) continue;
                if (i + 1 <= n && a[i + 1] == song[k + 1]) dp[i + 1][k + 1] = 1;
                if (i + 2 <= n && a[i + 2] == song[k + 1]) dp[i + 2][k + 1] = 1;
            }
        }

        int ok = 0;
        for (int i = 1; i <= n; i++) {
            if (dp[i][m]) {
                /* After reaching step i, angel must still be able to descend to ground.
                   Since moving +1 or +2 always allows reaching beyond n, any i is fine. */
                ok = 1;
                break;
            }
        }

        puts(ok ? "Yes" : "No");
    }
    return 0;
}

