public class Main {
    static final String[] NOTES = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
    static final Map<String, Integer> NOTE_TO_SEMITONE = new HashMap<>();

    static {
        for (int i = 0; i < 12; i++) {
            NOTE_TO_SEMITONE.put(NOTES[i], i);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNext()) {
            int n = sc.nextInt();
            if (n == 0) break;
            sc.nextLine(); // consume newline

            String[] plates = new String[n];
            for (int i = 0; i < n; i++) {
                plates[i] = sc.next();
            }
            sc.nextLine(); // consume newline

            String songLine = sc.nextLine();
            String[] songNotes = songLine.split(" ");
            int m = songNotes.length;

            // Convert to semitone indices
            int[] song = new int[m];
            for (int i = 0; i < m; i++) {
                song[i] = NOTE_TO_SEMITONE.get(songNotes[i]);
            }

            int[] plateSemitones = new int[n];
            for (int i = 0; i < n; i++) {
                plateSemitones[i] = NOTE_TO_SEMITONE.get(plates[i]);
            }

            boolean possible = false;
            // try all possible starting positions
            for (int start = 0; start < n; start++) {
                if (canPlay(plateSemitones, song, start)) {
                    possible = true;
                    break;
                }
            }

            System.out.println(possible ? "Yes" : "No");
        }
        sc.close();
    }

    static boolean canPlay(int[] plates, int[] song, int start) {
        int pos = start;
        int noteIndex = 0;
        int n = plates.length;
        int m = song.length;

        if (plates[pos] != song[0]) return false;
        noteIndex++;

        while (noteIndex < m) {
            int target = song[noteIndex];
            // check left or right neighbor
            if (pos > 0 && plates[pos - 1] == target) {
                pos--;
                noteIndex++;
            } else if (pos < n - 1 && plates[pos + 1] == target) {
                pos++;
                noteIndex++;
            } else {
                return false;
            }
        }
        return true;
    }
}

