public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int noteId(String s) {
        switch (s) {
            case "C": return 0;
            case "C#": return 1;
            case "D": return 2;
            case "D#": return 3;
            case "E": return 4;
            case "F": return 5;
            case "F#": return 6;
            case "G": return 7;
            case "G#": return 8;
            case "A": return 9;
            case "A#": return 10;
            case "B": return 11;
        }
        return -1;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            int n = Integer.parseInt(first);
            if (n == 0) break;

            int[] stairs = new int[n];
            for (int i = 0; i < n; i++) stairs[i] = noteId(fs.next());

            int m = fs.nextInt();
            int[] song = new int[m];
            for (int i = 0; i < m; i++) song[i] = noteId(fs.next());

            // dp[i][j]:
            // after producing first i notes of song,
            // angel is on stair j
            boolean[][] dp = new boolean[m + 1][n];

            // Start from the cloud side: first landing can be any stair.
            // A sound is produced only when landing on a stair.
            for (int j = 0; j < n; j++) {
                if (stairs[j] == song[0]) dp[1][j] = true;
            }

            for (int i = 1; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (!dp[i][j]) continue;

                    // Continue descending to any lower stair.
                    for (int nj = j + 1; nj < n; nj++) {
                        if (stairs[nj] == song[i]) {
                            dp[i + 1][nj] = true;
                        }
                    }
                }
            }

            boolean ok = false;
            for (int j = 0; j < n; j++) {
                if (dp[m][j]) {
                    ok = true;
                    break;
                }
            }

            out.append(ok ? "Yes" : "No").append('\n');
        }

        System.out.print(out.toString());
    }
}

