int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n != 0) {
        vector<int> stairs(n);
        for (int i = 0; i < n; i++) {
            string note;
            cin >> note;
            stairs[i] = noteToSemitone(note);
        }

        int m;
        cin >> m;
        vector<int> song(m);
        for (int i = 0; i < m; i++) {
            string note;
            cin >> note;
            song[i] = noteToSemitone(note);
        }

        // DP approach: can we match song starting from position pos?
        // We need to check if we can play the song while descending
        // The angel can move to adjacent steps (left or right)

        // For each starting position, check if we can play the song
        bool possible = false;

        // We'll use BFS/DFS with memoization
        // dp[pos][songIdx] = can we play song from songIdx starting at position pos?
        vector<vector<int>> memo(n, vector<int>(m, -1));

        function<bool(int, int)> dfs = [&](int pos, int songIdx) -> bool {
            if (songIdx == m) return true;
            if (pos < 0 || pos >= n) return false;
            if (memo[pos][songIdx] != -1) return memo[pos][songIdx];

            if (stairs[pos] != song[songIdx]) {
                return memo[pos][songIdx] = false;
            }

            // Try moving to adjacent steps for the next note
            bool result = false;
            if (pos > 0) result |= dfs(pos - 1, songIdx + 1);
            if (pos < n - 1) result |= dfs(pos + 1, songIdx + 1);

            return memo[pos][songIdx] = result;
        };

        // Try all possible starting positions
        for (int i = 0; i < n; i++) {
            if (dfs(i, 0)) {
                possible = true;
                break;
            }
        }

        cout << (possible ? "Yes" : "No") << "\n";
    }

    return 0;
}

