                if (j + 1 < n && dp[i - 1][j + 1]) dp[i][j] = 1;
            }
        }

        bool ok = false;
        for (int j = 0; j < n; ++j) {
            if (dp[m - 1][j]) {
                ok = true;
                break;
            }
        }

