import sys

NOTE_TO_INT = {
    'C': 0, 'C#': 1, 'D': 2, 'D#': 3, 'E': 4, 'F': 5,
    'F#': 6, 'G': 7, 'G#': 8, 'A': 9, 'A#': 10, 'B': 11
}

def can_play(stairs, song):
    n = len(stairs)
    m = len(song)

    if m == 0:
        return True
    if n == 0:
        return False

    # dp[i]: after matching current prefix of song, can be on stair i
    dp = [False] * n

    # First note: can start on any stair with that note
    first = song[0]
    for i in range(n):
        if stairs[i] == first:
            dp[i] = True

    for k in range(1, m):
        target = song[k]
        new_dp = [False] * n

        # From any reachable stair, can move to adjacent stair only
        for i in range(n):
            if not dp[i]:
                continue
            if i > 0 and stairs[i - 1] == target:
                new_dp[i - 1] = True
            if i + 1 < n and stairs[i + 1] == target:
                new_dp[i + 1] = True

        if not any(new_dp):
            return False
        dp = new_dp

    return any(dp)

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    out = []
    p = 0
    while p < len(data):
        n = int(data[p]); p += 1
        m = int(data[p]); p += 1

        if n == 0 and m == 0:
            break

        stairs = [NOTE_TO_INT[data[p + i]] for i in range(n)]
        p += n
        song = [NOTE_TO_INT[data[p + i]] for i in range(m)]
        p += m

        out.append("Yes" if can_play(stairs, song) else "No")

    sys.stdout.write("\n".join(out))

